testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Figura, Circulo, Quadrado } from './solution.mjs';

test('círculo calcula a área com pi', () => {
  const circulo = new Circulo(5);
  const esperado = Math.PI * 5 ** 2;
  assert.ok(Math.abs(circulo.area() - esperado) < 0.000001);
});

test('quadrado calcula a área com lado ao quadrado', () => {
  assert.equal(new Quadrado(4).area(), 16);
  assert.equal(new Quadrado(1).area(), 1);
});

test('mesmo método, comportamentos diferentes — e todos são Figura', () => {
  const circulo = new Circulo(5);
  const quadrado = new Quadrado(4);
  assert.equal(circulo instanceof Figura, true);
  assert.equal(quadrado instanceof Figura, true);
  assert.notEqual(circulo.area(), quadrado.area());
});

test('a classe base lança e as validações valem', () => {
  assert.throws(() => new Figura().area(), /subclasse/);
  assert.throws(() => new Circulo(0));
  assert.throws(() => new Quadrado('4'));
});

solutionCode:
// Figura é o contrato: o método existe, mas quem decide o valor é a filha.
export class Figura {
  area() {
    throw new Error('implemente area() na subclasse');
  }
}

// Circulo É UMA Figura: override de area() com o jeito do círculo.
export class Circulo extends Figura {
  constructor(raio) {
    super();
    if (typeof raio !== 'number' || raio <= 0) {
      throw new Error('raio precisa ser um número positivo');
    }
    this.raio = raio;
  }
  area() {
    return Math.PI * this.raio ** 2;
  }
}

// Quadrado É UMA Figura: override de area() com o jeito do quadrado.
export class Quadrado extends Figura {
  constructor(lado) {
    super();
    if (typeof lado !== 'number' || lado <= 0) {
      throw new Error('lado precisa ser um número positivo');
    }
    this.lado = lado;
  }
  area() {
    return this.lado ** 2;
  }
}
